Here is the extended C# code. I have added an optional `exportToCsv` parameter to the `GenerateReport` method. When enabled, it serializes the report data into a CSV format and prints it to the console (simulating an export).

```csharp
using System;
using System.Text;

public class SummaryReport
{
    public string Title { get; set; }
    public string Date { get; set; }
    public string Content { get; set; }

    public override string ToString()
    {
        return $"Title: {Title}\nDate: {Date}\nContent: {Content}";
    }
}

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportToCsv = false)
    {
        // Existing functionality: Output summary report
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // New functionality: Export to CSV if requested
        if (exportToCsv)
        {
            Console.WriteLine("\n--- CSV Export ---");
            string csv = ConvertToCsv(report);
            Console.WriteLine(csv);
        }
    }

    private string ConvertToCsv(SummaryReport report)
    {
        var sb = new StringBuilder();

        // Header row
        sb.AppendLine("Title,Date,Content");

        // Data row
        // Note: In a real-world scenario, you would need to escape commas and quotes in the content
        sb.AppendLine($"{EscapeCsvField(report.Title)},{EscapeCsvField(report.Date)},{EscapeCsvField(report.Content)}");

        return sb.ToString();
    }

    private string EscapeCsvField(string field)
    {
        if (string.IsNullOrEmpty(field)) return string.Empty;

        // If the field contains commas, quotes, or newlines, wrap it in quotes
        if (field.Contains(",") || field.Contains("\"") || field.Contains("\n"))
        {
            return "\"" + field.Replace("\"", "\"\"") + "\"";
        }
        return field;
    }
}
```

